mapper.select:
SELECT
FROM patient_doctor_apply a INNER JOIN patient p ON p.id = a.patient_id AND p.deleted = 0 LEFT JOIN sys_user d ON d.id = a.doctor_id AND d.deleted = 0 LEFT JOIN sys_user h ON h.id = a.handle_by AND h.deleted = 0 WHERE a.deleted = 0
AND a.status = #{query.status}
AND a.apply_type = #{query.applyType}
AND p.name LIKE CONCAT('%', #{query.patientName}, '%')
AND d.real_name LIKE CONCAT('%', #{query.doctorName}, '%')
AND a.doctor_id = #{doctorId}
ORDER BY a.status ASC, a.create_time DESC, a.id DESC
